#define ADDR_NO_RANDOMIZE 0x0040000UL
unsigned long RETRIEVE_ONLY = 0xffffffffUL;

// 1. Retrieve current execution domain (no change)
unsigned long current_p = personality(RETRIEVE_ONLY);

// 2. Define new desired persona (e.g., add flag)
unsigned long desired_p = current_p | ADDR_NO_RANDOMIZE;

// 3. Set the new persona; returns previous value
long old_p = personality(desired_p);

// Error Handling Check
if (old_p == -1L) {
    // errno == EINVAL: Invalid combination of flags
}

// Revert if successful
if (old_p != -1L) {
    personality(old_p);
}
